files.total.js:
export function total(items) {
  return items.reduce((n, it) => n + it.price * it.qty, 0);
}

files.test.mjs:
import { total } from './total.js';

const cart = [{ price: 2, qty: 3 }];
if (total(cart) !== 6) { console.error('total should be 6'); process.exit(1); }
if (total(cart) !== 7) { console.error('total should be 7'); process.exit(1); }
console.log('ok');

